            for (n2, y) in layoutVariants(COL){
                XCTAssertClose(x + y, MfArray([5.0, 1.0, 2.0, 3.0, 2.0, 6.0, -5.0, 3.0, 5.5, -2.5, 5.5, 8.5] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x + y \(n1) \(n2)")
